mapper.select:
SELECT `dev`.`id`, `dev`.`device_name`, `dev`.`device_code`, `dev`.`department_id`, `dev`.`device_iot_prod_id` AS `iotProductId`, `dev`.`area_name`, `dev`.`area_id`, `dev`.`area_last_id`, `dev`.`device_state`, `dev`.`thirdparty_id`, `dev`.`communication_time`, `dev`.`department_name`, `cbde`.`lnt_and_lat`, `cbde`.`location_des`, `cbde`.`picture`, `iot_prod`.`prod_name` AS `iotProductName`, `iot_prod`.`prod_model_name` AS `iotModelName`, `iot_prod`.`prod_brand_name` AS `iotBrandName`, `iot_prod`.`prod_pic` AS `iotProductPicture`, `iot_prod`.`prod_icon` AS `iotProductIcon`, `iot_prod`.`prod_category_name` AS `iotProductCategoryName`, `iot_prod`.`prod_category_name_concat` AS `iotProductCategoryNameConcat`, `iot_prod`.`prod_category_code` AS `iotProductCategoryCode`, `iot_prod`.`prod_category_concat` AS `iotProductCategoryCodeConcat` FROM `center_biz_device` `dev` LEFT JOIN `iot_prod_view` `iot_prod` ON `dev`.`device_iot_prod_id` = `iot_prod`.`id` LEFT JOIN `center_biz_device_expand` `cbde` ON `cbde`.`id` = `dev`.`id` inner JOIN `center_biz_group_ref` `cbgr` ON `dev`.`id` = `cbgr`.`device_id` INNER JOIN `center_biz_tag_ref` `cbtr` on `cbtr`.business_key =`cbgr`.device_id
`cbgr`.`group_id` = #{param.id} and `cbtr`.`tag_id` = #{tagId}
GROUP BY `dev`.`id` ORDER BY `dev`.`create_time` DESC, `dev`.`id` DESC

SELECT `dev`.`id`, `dev`.`device_name`, `dev`.`device_code`, `dev`.`department_id`, `dev`.`device_iot_prod_id` AS `iotProductId`, `dev`.`area_name`, `dev`.`area_id`, `dev`.`area_last_id`, `dev`.`device_state`, `dev`.`thirdparty_id`, `dev`.`communication_time`, `dev`.`department_name`, `cbde`.`lnt_and_lat`, `cbde`.`location_des`, `cbde`.`picture`, `iot_prod`.`prod_name` AS `iotProductName`, `iot_prod`.`prod_model_name` AS `iotModelName`, `iot_prod`.`prod_brand_name` AS `iotBrandName`, `iot_prod`.`prod_pic` AS `iotProductPicture`, `iot_prod`.`prod_icon` AS `iotProductIcon`, `iot_prod`.`prod_category_name` AS `iotProductCategoryName`, `iot_prod`.`prod_category_name_concat` AS `iotProductCategoryNameConcat`, `iot_prod`.`prod_category_code` AS `iotProductCategoryCode`, `iot_prod`.`prod_category_concat` AS `iotProductCategoryCodeConcat` FROM `center_biz_device` `dev` LEFT JOIN `iot_prod_view` `iot_prod` ON `dev`.`device_iot_prod_id` = `iot_prod`.`id` LEFT JOIN `center_biz_device_expand` `cbde` ON `cbde`.`id` = `dev`.`id` inner JOIN `center_biz_group_ref` `cbgr` ON `dev`.`id` = `cbgr`.`device_id` INNER JOIN `center_biz_tag_ref` `cbtr` on `cbtr`.business_key =`cbgr`.device_id inner join `center_biz_tag` `cbt` on `cbtr`.tag_id = `cbt`.id
`cbt`.`tag_code` = #{param.tagCode}
and `cbgr`.`group_id` in
#{groupId}
GROUP BY `dev`.`id` ORDER BY `dev`.`create_time` DESC, `dev`.`id` DESC

SELECT `cbg`.`id`, `cbg`.`name`, `cbg`.`remark`, `dev`.`id` as device_id, `dev`.`device_name`, `dev`.`device_code`, `dev`.`department_id`, `dev`.`device_iot_prod_id` AS `iotProductId`, `dev`.`area_name`, `dev`.`area_id`, `dev`.`area_last_id`, `dev`.`device_state`, `dev`.`thirdparty_id`, `dev`.`communication_time`, `dev`.`department_name` FROM `center_biz_group` `cbg` INNER JOIN `center_biz_group_ref` `cbgf` ON `cbg`.id = `cbgf`.group_id INNER JOIN `center_biz_tag_ref` `cbtr` on `cbtr`.business_key =`cbgf`.device_id INNER JOIN `center_biz_device` `dev` ON `cbgf`.device_id = `dev`.id
`cbtr`.`tag_id` = #{tagId}
and `cbg`.`id` in
#{id}
and `dev`.id in
#{deviceId}
and `dev`.`device_name` like concat('%',#{deviceName},'%')
